package org.rabochaya.projects;
import android.content.*;import android.util.Base64;import java.io.*;import java.util.*;
/** Per-project composition preferences, atomically replaced without touching map/cache/project files. */
public final class MapCompositionSettings {
 private MapCompositionSettings(){}
 private static SharedPreferences prefs(Context c){return c.getSharedPreferences("map-compositions",0);}
 public static final class Snapshot {public final MapComposition composition;public final boolean enabled;private final String raw;private Snapshot(MapComposition c,boolean enabled,String raw){composition=c;this.enabled=enabled;this.raw=raw;}}
 private static String key(long project){if(project<=0)throw new IllegalArgumentException("Нужен существующий проект");return "composition_"+project;}
 private static String activeKey(long project){return "enabled_"+project;}
 public static synchronized boolean active(Context c,long project){return project>0&&prefs(c).getBoolean(activeKey(project),false);}
 public static synchronized Snapshot load(Context c,long project)throws IOException{String raw=prefs(c).getString(key(project),null);boolean enabled=active(c,project);if(raw!=null){try{if(raw.length()>180000)throw new IllegalArgumentException();return new Snapshot(MapComposition.decode(Base64.decode(raw,Base64.NO_WRAP),project),enabled,raw);}catch(IllegalArgumentException e){throw new IOException("Состав карт повреждён; настройки сохранены для восстановления",e);}}if(enabled)throw new IOException("Сохранённый состав карт не найден");List<MapComposition.Layer> initial=new ArrayList<>();if(OnlineMapSettings.active(c,project)){String catalog=OnlineMapSettings.prefs(c).getString("catalog","");initial.add(!catalog.isEmpty()&&MapCatalog.find(catalog)!=null?MapComposition.Layer.catalog(catalog):MapComposition.Layer.custom(OnlineMapSettings.source(c)));}else if(new File(c.getFilesDir(),"local_basemap_"+project+".mbtiles").isFile())initial.add(MapComposition.Layer.local());else initial.add(MapComposition.Layer.bundled());return new Snapshot(new MapComposition(project,initial),false,null);}
 public static synchronized Snapshot save(Context c,long project,Snapshot previous,MapComposition next,boolean enabled)throws IOException{if(previous==null||previous.composition.project!=project||next.project!=project)throw new IOException("Состав относится к другому проекту");SharedPreferences p=prefs(c);if(!Objects.equals(p.getString(key(project),null),previous.raw)||p.getBoolean(activeKey(project),false)!=previous.enabled)throw new IOException("Состав изменился в другом окне. Откройте менеджер повторно");String raw=Base64.encodeToString(next.encode(),Base64.NO_WRAP);if(!p.edit().putString(key(project),raw).putBoolean(activeKey(project),enabled).commit())throw new IOException("Не удалось сохранить состав карт");return new Snapshot(next,enabled,raw);}
 public static final class PresetsSnapshot {public final MapCompositionPresets presets;private final String raw;private PresetsSnapshot(MapCompositionPresets presets,String raw){this.presets=presets;this.raw=raw;}}
 private static String presetsKey(long project){key(project);return "presets_"+project;}
 private static void existing(Context c,long project)throws IOException{ProjectStore store=new ProjectStore(c);try{if(!store.exists(project))throw new IOException("Проект больше не существует");}finally{store.close();}}
 public static synchronized PresetsSnapshot loadPresets(Context c,long project)throws IOException{existing(c,project);String raw=prefs(c).getString(presetsKey(project),null);if(raw==null)return new PresetsSnapshot(new MapCompositionPresets(project),null);try{if(raw.length()>700000)throw new IllegalArgumentException();return new PresetsSnapshot(MapCompositionPresets.decode(Base64.decode(raw,Base64.NO_WRAP),project),raw);}catch(IllegalArgumentException e){throw new IOException("Библиотека наборов повреждена; сохранённые настройки не изменены",e);}}
 private static void presetsMatch(Context c,long project,PresetsSnapshot previous)throws IOException{existing(c,project);if(previous==null||previous.presets.project!=project)throw new IOException("Библиотека относится к другому проекту");if(!Objects.equals(prefs(c).getString(presetsKey(project),null),previous.raw))throw new IOException("Наборы изменились в другом окне. Откройте список повторно");}
 private static void compositionMatch(Context c,long project,Snapshot previous)throws IOException{if(previous==null||previous.composition.project!=project)throw new IOException("Состав относится к другому проекту");SharedPreferences p=prefs(c);if(!Objects.equals(p.getString(key(project),null),previous.raw)||p.getBoolean(activeKey(project),false)!=previous.enabled)throw new IOException("Состав изменился в другом окне. Откройте менеджер повторно");}
 private static PresetsSnapshot writePresets(Context c,long project,MapCompositionPresets next)throws IOException{String raw=Base64.encodeToString(next.encode(),Base64.NO_WRAP);if(!prefs(c).edit().putString(presetsKey(project),raw).commit())throw new IOException("Не удалось сохранить библиотеку наборов");return new PresetsSnapshot(next,raw);}
 public static synchronized PresetsSnapshot savePreset(Context c,long project,PresetsSnapshot previous,Snapshot composition,String name)throws IOException{presetsMatch(c,project,previous);compositionMatch(c,project,composition);return writePresets(c,project,previous.presets.add(name,composition.composition));}
 public static synchronized PresetsSnapshot deletePreset(Context c,long project,PresetsSnapshot previous,String name)throws IOException{presetsMatch(c,project,previous);return writePresets(c,project,previous.presets.remove(name));}
 public static synchronized Snapshot applyPreset(Context c,long project,Snapshot previous,PresetsSnapshot presets,String name)throws IOException{presetsMatch(c,project,presets);compositionMatch(c,project,previous);MapCompositionPresets.Entry entry=presets.presets.find(name);if(entry==null)throw new IOException("Набор больше не найден");return save(c,project,previous,entry.composition,true);}
 /** An explicit legacy single-map choice suspends the stack, but preserves it for later use. */
 public static synchronized void suspend(Context c,long project){if(project>0&&active(c,project)&&!prefs(c).edit().putBoolean(activeKey(project),false).commit())throw new IllegalStateException("Не удалось переключить подложку карты");}
 public static synchronized void removeDeletedProject(Context c,long project){if(project>0)prefs(c).edit().remove(key(project)).remove(activeKey(project)).remove(presetsKey(project)).commit();}
}
